mutants.replacement:
this.#hunks.some(hunk => !touches({
  start: hunk.oldStart,
  count: hunk.oldLines
}, old) && !touches({
  start: hunk.newStart,
  count: hunk.newLines
}, current))

!touches({
  start: hunk.oldStart,
  count: hunk.oldLines
}, old) || !touches({
  start: hunk.newStart,
  count: hunk.newLines
}, current)

touches({
  start: hunk.oldStart,
  count: hunk.oldLines
}, old)

touches({
  start: hunk.newStart,
  count: hunk.newLines
}, current)
